"""Build portable HTML research outputs from the curated article register."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'
ARTICLES = [
    {'title': 'The Untold Story behind Africa’s Most Valuable Fintech Spinout', 'url': 'https://legesi.substack.com/p/the-untold-story-behind-africas-most', 'role': 'Original fintech and sum-of-the-parts thesis', 'date': '2025-05-07'},
    {'title': 'The Illusion of Ownership: What MTN Uganda’s MoMo Restructure Means for Investors', 'url': 'https://legesi.substack.com/p/the-illusion-of-ownership-what-mtn', 'role': 'Minority rights and value-realisation risk', 'date': '2025-06-16'},
    {'title': 'The Gem Inside the Rump', 'url': 'https://legesi.substack.com/p/the-gem-inside-the-rump', 'role': 'Embedded optionality and scenario framework', 'date': ''},
]
CSS = '''body{margin:0;background:#f5f3ec;color:#19252c;font:17px/1.65 system-ui,sans-serif}header,main,footer{max-width:1060px;margin:auto;padding:32px 24px}header{border-bottom:3px solid #d1a83a}h1{font:600 clamp(32px,5vw,58px)/1.12 Georgia,serif;max-width:850px}h2{font:600 28px/1.25 Georgia,serif;margin-top:38px}h3{font-size:19px}a{color:#146a77}nav{display:flex;gap:20px;flex-wrap:wrap}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase}.lead{font-size:21px;max-width:820px}.notice{background:#e8edf0;padding:18px;border-left:4px solid #146a77}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:18px}.card{background:white;border:1px solid #deded5;padding:24px;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:15px}th,td{text-align:left;padding:14px;border-bottom:1px solid #d9ddd9;vertical-align:top}th{background:#e8ece6}small,footer{color:#52636a}button{padding:10px;border:1px solid #52636a;background:white;cursor:pointer}@media print{nav,button{display:none}body{background:white}header,main,footer{padding:15px}h1{font-size:36px}.card{break-inside:avoid}}'''

def refs():
    return '<div class="cards">' + ''.join('<article class="card"><h3><a href="'+html.escape(a['url'], quote=True)+'">'+html.escape(a['title'])+'</a></h3><p>'+html.escape(a['role'])+'</p><small>'+html.escape(a['date'] or 'Publication date to be confirmed')+'</small></article>' for a in ARTICLES) + '</div>'

def page(title, lead, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Legesi Investment Research</title><style>{CSS}</style></head><body><header><p class="eyebrow">Legesi Investment Research · MTN Uganda</p><nav><a href="index.html">Coverage</a><a href="valuation.html">Valuation</a><a href="ownership.html">Ownership</a><a href="substack.html">Substack articles</a></nav><h1>{html.escape(title)}</h1><p class="lead">{lead}</p><small>Prepared 13 October 2026 · Kenneth S. Legesi, CFA</small></header><main><p class="notice"><strong>Research status:</strong> Synthesis of published articles and a framework for ongoing coverage. Historical article claims have not been independently refreshed against current issuer filings. No current rating, target price or market quotation is asserted.</p>{body}</main><footer><p>Independent research for general information. Read the source articles in their publication context. Estimates and analyst judgments must be distinguished from reported facts.</p><a href="https://legesi.substack.com/">Read Risk is a Privilege on Substack</a> · <a href="https://legesi.substack.com/feed">Subscribe via RSS</a> · <button onclick="window.print()">Print / save PDF</button></footer></body></html>'''

def build():
    DOCS.mkdir(exist_ok=True)
    body = '''<h2>The investment question</h2><p>The research sequence asks whether a telecom valuation obscures a financial-services asset, then whether the listed investor can actually capture that asset’s value. These are separate tests: attractive operating economics do not establish enforceable shareholder participation.</p><div class="cards"><div class="card"><h3>Value</h3><p>Estimate telecoms and MoMo independently, with consistent earnings definitions and a reconciled enterprise-to-equity bridge.</p></div><div class="card"><h3>Rights</h3><p>Trace the listed share through the separation and any trust or FinCo entitlement. Verify distributions, control, dilution and exit.</p></div><div class="card"><h3>Realisation</h3><p>Model dividends, delays, partial monetisation and deterioration. A paper valuation gap is not an investor cash flow.</p></div></div><h2>How the thesis evolved</h2><table><tr><th>Published research</th><th>Coverage implication</th></tr><tr><td>Fintech spinout thesis</td><td>Separate business economics and comparable valuation frameworks.</td></tr><tr><td>Illusion of ownership</td><td>Make governance and enforceable participation central to valuation.</td></tr><tr><td>Gem inside the Rump</td><td>Test asymmetric returns with explicit downside, timing and probabilities.</td></tr></table><h2>What would support or weaken the thesis?</h2><p>Support would come from segment cash generation, transparent financial reporting and documented value-transfer mechanisms. Weakness would include adverse separation terms, capital leakage, dilution, sustained telecom deterioration or an exit path dependent on indefinite discretion.</p><h2>Published foundations</h2>'''+refs()+'''<h2>Coverage work still required</h2><p>Reconcile all project workbooks and source documents; verify current corporate structure and entitlements; refresh financials, debt, leases, shares, price and dividends; then reproduce scenarios and publish a dated investment assessment. Existing graphics are historical illustrations until tied to those inputs.</p>'''
    (DOCS/'index.html').write_text(page('The telecom, the fintech and the shareholder', 'A coverage framework guided by the published MTN articles: what is the asset worth, who owns the upside, and when can it become cash?', body), encoding='utf-8')
    body = '''<h2>Value each business, then value the investor’s claim</h2><p>The original fintech article motivates a telecoms/MoMo sum-of-the-parts approach. Transaction and public-market comparisons provide reference points, but differences in geography, margins, growth, regulatory scope and control require explicit adjustments.</p><table><tr><th>Step</th><th>Required calculation</th><th>Key control</th></tr><tr><td>Telecom</td><td>Cash-flow valuation and comparable earnings multiples</td><td>Separate MoMo contributions and intercompany charges.</td></tr><tr><td>MoMo</td><td>Cash-flow valuation and relevant fintech benchmarks</td><td>Do not treat transaction throughput as revenue; distinguish EV from equity value.</td></tr><tr><td>Financing</td><td>Debt, cash, leases and other claims</td><td>Apply consistent lease treatment; avoid double deductions.</td></tr><tr><td>Shareholder entitlement</td><td>Value of rights attached to the purchased security</td><td>Verify record dates, transferability and dilution before adding FinCo value.</td></tr><tr><td>Return</td><td>Dated distributions and exit proceeds against purchase cost</td><td>Include timing, tax assumptions, liquidity and currency effects.</td></tr></table><h2>Scenario architecture</h2><p>Full unlock, partial unlock, status quo and deterioration should use explicit cash flows. Do not assume the original probabilities or return ranges remain valid. Calculate scenario IRRs separately and probability-weight terminal wealth or NPV at a stated horizon; an average of IRRs is only a descriptive approximation.</p><h2>Price discipline</h2><p>The embedded-option argument is strongest when conservative value of the core business supports the entry price. That downside support still depends on operating resilience and the balance sheet. A valuable subsidiary does not make the telecom floor guaranteed.</p><h2>Published sources</h2>'''+refs()
    (DOCS/'valuation.html').write_text(page('From sum of the parts to investor returns', 'A reproducible valuation pathway, with shareholder rights and realisation timing built into the equity bridge.',body),encoding='utf-8')
    body = '''<h2>Ownership is a valuation input</h2><p>The June 2025 article challenges whether indirect exposure preserves meaningful shareholder rights. Its description of a proposed restructuring is historical evidence of the author’s concern, not proof of the structure implemented today.</p><p>Coverage must distinguish a proposal, shareholder approval, regulatory approval, legal completion and distributions actually received. Each transition needs dated evidence.</p><table><tr><th>Question</th><th>Evidence required</th><th>Investor consequence</th></tr><tr><td>Who holds the claim?</td><td>Final transaction documents, trust deed and entitlement register</td><td>Determines whether a current buyer receives fintech participation.</td></tr><tr><td>Can investors see the economics?</td><td>Reporting obligations and published FinCo accounts</td><td>Determines confidence in earnings and cash-flow valuation.</td></tr><tr><td>Who decides distributions?</td><td>Dividend terms, trustee powers and governance documents</td><td>Changes payout assumptions and timing risk.</td></tr><tr><td>Can the claim be diluted?</td><td>Issuance terms and pre-emption protections</td><td>Changes attributable value.</td></tr><tr><td>Can the investor exit?</td><td>Transfer provisions, redemption terms and binding listing commitments</td><td>Changes liquidity and realisation assumptions.</td></tr></table><h2>Modelling consequence</h2><p>A telecom share and a separate trust entitlement may require distinct valuations. Do not automatically attach legacy fintech rights to shares purchased after a qualifying record date. Model access, distributions and exit according to the verified instrument terms.</p><h2>Published foundation</h2>'''+refs()
    (DOCS/'ownership.html').write_text(page('Can the shareholder capture the Gem?', 'Governance, economic rights and liquidity determine how operating value translates into investable value.',body),encoding='utf-8')
    extra = []
    cache=DOCS/'substack-articles.json'
    if cache.exists():
        extra=json.loads(cache.read_text()).get('articles',[])
    seen={a['url'] for a in ARTICLES}
    links=''.join('<li><a href="'+html.escape(a['url'],quote=True)+'">'+html.escape(a['title'])+'</a> — '+html.escape(a.get('date',''))+'</li>' for a in extra if a['url'] not in seen)
    body='<h2>Canonical MTN reading list</h2>'+refs()+('<h2>Additional RSS discoveries</h2><ul>'+links+'</ul>' if links else '')+'''<h2>Follow future articles</h2><p><a href="https://legesi.substack.com/feed">Open the publication RSS feed</a> or <a href="https://legesi.substack.com/">visit Substack</a>. The curated links remain available even if the feed omits older posts or is unavailable.</p><h2>Publication relationship</h2><p>Substack is the article home. These HTML reports provide the coverage synthesis and supporting methodology. The refresh script stores only titles, dates and canonical links; it does not mirror article bodies or change investment conclusions.</p>'''
    (DOCS/'substack.html').write_text(page('The published articles behind the coverage', 'Follow the argument from fintech value to minority rights and embedded optionality.',body),encoding='utf-8')
    (DOCS/'article-register.json').write_text(json.dumps(ARTICLES,ensure_ascii=False,indent=2),encoding='utf-8')

if __name__=='__main__': build()
